                            elide: Text.ElideMiddle
                            color: mlBridge.segmentFemPt.length > 0
                                   ? Theme.fg : Theme.fgMuted
                            font.pixelSize: 10
                            text: mlBridge.segmentFemPt.length > 0
                                  ? baseName(mlBridge.segmentFemPt)
                                  : qsTr("not set")
                        }
