import QtQuick
import QtQuick.Layouts
import QtQuick.Controls
import "."  // Theme

// 007 U2: left column study lists (extracted from main.qml): frame list
// (current-frame contract) over the model list (bridge-owned multi-select)
// + the selection summary. Delegate selection contract unchanged — no
// QItemSelectionModel; currentIndex drives the bridge. The onDatasetChanged
// relay keeps the Qt.callLater deferral (outlasts the clearDataset list-
// model swap).

ColumnLayout {
    id: root
    Layout.fillWidth: true
    spacing: 6

    // Frame list (delegate selection contract: currentIndex drives the
    // bridge — no QItemSelectionModel).
    Label {
        text: qsTr("Frames (%1)").arg(appBridge.frameCount)
        color: Theme.fg
        font.bold: true
        font.pixelSize: Theme.label
    }
    ListView {
        id: frameList
        Layout.fillWidth: true
        Layout.fillHeight: true
        clip: true
        enabled: !optimizerBridge.running
        model: studyBridge.frameListModel
        delegate: Rectangle {
            required property string display
            width: ListView.view.width
            height: 22
            color: ListView.view.currentIndex === index
                   ? Theme.selection : "transparent"
            Text {
                anchors.fill: parent
                anchors.leftMargin: 4
                verticalAlignment: Text.AlignVCenter
                color: Theme.fg
                text: display
                elide: Text.ElideRight
            }
            MouseArea {
                anchors.fill: parent
                onClicked: {
