The script:
```cmake
cmake_minimum_required(VERSION 3.19)
if(NOT DEFINED QML_LINT)
    message(FATAL_ERROR "qml_lint.cmake: QML_LINT not passed")
endif()
file(GLOB QML_FILES "${QML_DIR}/*.qml")
if(NOT QML_FILES)
    message(FATAL_ERROR "qml_lint.cmake: no .qml files in ${QML_DIR}")
endif()
execute_process(
    COMMAND "${QML_LINT}" --json "${QML_OUT}" -I "${QML_DIR}" ${QML_FILES}
    RESULT_VARIABLE rc)
if(NOT rc EQUAL 0)
    message(FATAL_ERROR "qmllint exited ${rc}")
endif()
file(READ "${QML_OUT}" json)
string(JSON nfiles LENGTH "${json}" files)
math(EXPR nfiles "${nfiles} - 1")
set(bad "")
foreach(i RANGE 0 ${nfiles})
    string(JSON fname MEMBER "${json}" files ${i} filename)
    string(JSON success MEMBER "${json}" files ${i} success)
    if(NOT success)
        string(APPEND bad "  ${fname}: parse/success=false\n")
    endif()
    string(JSON nwarn LENGTH "${json}" files ${i} warnings)
    if(nwarn GREATER 0)
        math(EXPR nwarn "${nwarn} - 1")
        foreach(j RANGE 0 ${nwarn})
            string(JSON wid MEMBER "${json}" files ${i} warnings ${j} id)
            string(JSON wtype MEMBER "${json}" files ${i} warnings ${j} type)
            string(JSON wline MEMBER "${json}" files ${i} warnings ${j} line)
            string(JSON wmsg MEMBER "${json}" files ${i} warnings ${j} message)
            set(accepted FALSE)
            if(wtype STREQUAL "error")
                set(accepted FALSE)
            elseif(wid STREQUAL "import" OR wid STREQUAL "unqualified"
                   OR wid STREQUAL "unresolved-type"
                   OR wid STREQUAL "missing-property"
                   OR wid STREQUAL "use-proper-function")
                set(accepted TRUE)
            endif()
            if(NOT accepted)
                string(APPEND bad "  ${fname}:${wline}: [${wid}] ${wmsg}\n")
            endif()
        endforeach()
    endif()
endforeach()
if(bad)
    message(FATAL_ERROR "qmllint gate FAILED — non-accepted warnings:\n${bad}")
endif()
message(STATUS "qmllint gate PASSED (only documented-accepted warnings)")
```
