// Theme.qml — the experimental app's palette + type scale (plan 005
// feedback #6: all color/text choices live here, not scattered through
// the shell). Singleton (pragma + qmldir) so every file shares one
// instance. Plan 007 U2: badge-pill tokens + TypeScale roles added; the
// scale is pinned (major second 1.125 from base 16) and applied by U2,
// verified by U4.
pragma Singleton
import QtQuick

QtObject {
    id: root

    // ---- Palette --------------------------------------------------------
    readonly property color bg: "#14161a"          // window background
    readonly property color panel: "#1b1e24"       // panels / list areas
    readonly property color surface: "#101216"     // viewport placeholder
    readonly property color border: "#2a2f38"
    readonly property color fg: "#e6e9ee"          // primary text (light)
    readonly property color fgMuted: "#8b929c"     // secondary text
    readonly property color fgDim: "#6b7280"       // placeholders / hints
    readonly property color selection: "#2a4a7a"   // list highlight
    readonly property color ok: "#5a8a5f"          // calibrated / good
    readonly property color accent: "#4a90d9"      // interactive accents
    readonly property color badge: "#c0392b"       // errors / debug readout
    // Dirty/unsaved pill (dirty = unsaved amber, clean = saved green).
    readonly property color badgeDirtyBg: "#e5b567"
    readonly property color badgeDirtyFg: "#2a2118"
    readonly property color badgeCleanBg: "#3a4a3d"
    readonly property color badgeCleanFg: "#8fbf96"
    readonly property color badgeText: "#ffffff"   // text on Theme.badge

    // ---- Type scale (pinned: major second 1.125 from base 16) ----------
    readonly property real caption: 12             // metadata / labels
    readonly property real label: 14               // section headers
    readonly property real body: 16                // primary reading
    readonly property real h2: 18                  // panel titles
}

import QtQuick
import QtQuick.Controls
import "."  // Theme

// 005 U8: one editable pose cell of the Poses dialog table. Pure view glue
// (no logic — the commit + validation live in PoseBridge):
//  - the stored value comes from the table model's role (re-reads on
//    dataChanged / table reset — the model is the authoritative display
//    source);
//  - on editingFinished the text commits through PoseBridge::setPoseValue
//    (immediate per-cell SavePose). A rejected commit (non-numeric / NaN /
//    out-of-range) leaves the stored state unchanged: the field reverts to
//    the stored value and the bridge's inline validation message shows.
//
// Inline components are not supported in engine-root documents (main.qml is
// loaded by URL), so this is a regular QML file registered via qmldir.
// 007 U2: explicit width/height -> implicitWidth/implicitHeight (LAY-2:
// the cell is consumed inside a RowLayout; explicit width on a
// layout-managed item is undefined behavior per qmllint).
TextField {
    id: root

    required property int frameRow
    required property int axisIndex
    required property double storedValue

    text: storedValue.toFixed(3)
    implicitWidth: 78
    implicitHeight: 26
    font.pixelSize: Theme.caption
    horizontalAlignment: Text.AlignRight
    selectByMouse: true

    onEditingFinished: {
        // The user's typing has broken the text binding; a rejected commit
        // restores the stored value with a plain assignment (the stored
        // value is current — full table refreshes recreate this delegate).
        // 007 U3 replaces this with the capture-at-edit-start contract.
        if (!poseBridge.setPoseValue(frameRow,
                                     studyBridge.primaryModelIndex,
                                     axisIndex, text)) {
            text = storedValue.toFixed(3)
        }
    }
}

import QtQuick
import jtml.experimental 1.0

// 005 U3: the QML render smoke scene — one QmlVtkRenderer filling the
// window. The C++ driver (test/oracle/qml_render_smoke.cpp) binds the
// app-owned ExperimentalScene and drives the renderer's GUI-thread slots
// (applyScene/updatePose/updateBackground) through the dispatch_async
// render-thread contract. 007 U2: QtQuick.Window import dropped (Window
// resolves from QtQuick in Qt 6).

Window {
    id: root
    visible: true
    width: 640
    height: 640
    title: qsTr("JTML QML renderer smoke (plan 005 U3)")
    color: "#14161a"

    QmlVtkRenderer {
        id: vtkItem
        anchors.fill: parent
    }
}

