import QtQuick
import QtQuick.Layouts
import QtQuick.Controls
import "."  // Theme

// 007 U2: left-column study lists (extracted from main.qml): the frame
// list (current-frame contract) over the model list (bridge-owned
// multi-select) + the selection summary. Delegate selection contract
// unchanged — no QItemSelectionModel; currentIndex drives the bridge.
// The onDatasetChanged relay keeps the Qt.callLater deferral (it outlasts
// the clearDataset list-model swap). 007 U2 review fixes: delegate root-id
// references converted to ListView.view + required properties (I-04).

ColumnLayout {
    id: root
    Layout.fillWidth: true
    Layout.fillHeight: true
    spacing: 6

    // Frame list (delegate selection contract: currentIndex drives the
    // bridge — no QItemSelectionModel).
    Label {
        text: qsTr("Frames (%1)").arg(appBridge.frameCount)
        color: Theme.fg
        font.bold: true
        font.pixelSize: Theme.label
    }
    ListView {
        id: frameList
        Layout.fillWidth: true
        Layout.fillHeight: true
        clip: true
        enabled: !optimizerBridge.running
        model: studyBridge.frameListModel
        delegate: Rectangle {
            required property string display
            width: ListView.view.width
            height: 22
            color: ListView.view.currentIndex === index
                   ? Theme.selection : "transparent"
            Text {
                anchors.fill: parent
                anchors.leftMargin: 4
                verticalAlignment: Text.AlignVCenter
                color: Theme.fg
                text: display
                elide: Text.ElideRight
            }
            MouseArea {
                anchors.fill: parent
                onClicked: {
                    ListView.view.currentIndex = index
                    studyBridge.setCurrentFrame(index)
                }
            }
        }
        highlightFollowsCurrentItem: true
    }

    // Model list (multi-select via the bridge-owned set).
    Label {
        text: qsTr("Models (%1)").arg(appBridge.modelCount)
        color: Theme.fg
        font.bold: true
        font.pixelSize: Theme.label
    }
    ListView {
        id: modelList
        Layout.fillWidth: true
        Layout.fillHeight: true
        clip: true
        enabled: !optimizerBridge.running
        model: studyBridge.modelListModel
        delegate: Rectangle {
            required property string display
            width: ListView.view.width
            height: 22
            color: studyBridge.selectedModels.indexOf(index) !== -1
                   ? Theme.selection : "transparent"
            Text {
                anchors.fill: parent
                anchors.leftMargin: 4
                verticalAlignment: Text.AlignVCenter
                color: Theme.fg
                text: display
                elide: Text.ElideRight
            }
            MouseArea {
                anchors.fill: parent
                onClicked: studyBridge.toggleModelSelected(index)
            }
        }
    }
    Label {
        text: studyBridge.selectedModelCount > 0
              ? qsTr("Selected %1 · primary %2")
                    .arg(studyBridge.selectedModelCount)
                    .arg(studyBridge.primaryModelIndex)
              : qsTr("No model selected")
        color: Theme.fgMuted
        font.pixelSize: Theme.caption
    }

    // Dataset-changed relay (moved with the lists): the deferral outlasts
    // the list-model swap (clearDataset deletes the old model instance).
    Connections {
        target: studyBridge
        function onDatasetChanged() {
            Qt.callLater(function() {
                frameList.currentIndex = studyBridge.currentFrame
            })
        }
    }
}

import QtQuick
import QtQuick.Layouts
import QtQuick.Controls
import QtQuick.Dialogs
import "."  // Theme

// 007 U2: ML controls strip (extracted from main.qml, U7 surface):
// per-implant .pt pickers + Segment/Estimate + the black-silhouette /
// implant-kind / view rows + estimate/status labels. Self-contained: the
// three .pt FileDialogs moved in with the strip. Behavior unchanged (AE4
// degradation, run-lock via optimizerBridge.running).

ColumnLayout {
    id: root
    Layout.fillWidth: true
    spacing: 6

    // Loaded-.pt label helper: the last path segment (the full path is in
    // the bridge's property; the strip shows the basename to fit the
    // 240px column).
    function baseName(path) {
        const parts = String(path).split('/')
        return parts[parts.length - 1]
    }

    // ---- .pt pickers (per-implant segment + one estimate) --------------
    // The loaded path/state is shown in the strip; the bridge normalizes
    // file:// URLs to local paths.
    FileDialog {
        id: segFemPtDialog
        title: qsTr("Load Femur Segmentation Model (.pt)")
        nameFilters: ["Torch File (*.pt)", "All files (*)"]
        onAccepted: mlBridge.setSegmentFemPt(selectedFile)
    }
    FileDialog {
        id: segTibPtDialog
        title: qsTr("Load Tibia Segmentation Model (.pt)")
        nameFilters: ["Torch File (*.pt)", "All files (*)"]
        onAccepted: mlBridge.setSegmentTibPt(selectedFile)
    }
    FileDialog {
        id: estimatePtDialog
        title: qsTr("Load Pose Estimation Model (.pt)")
        nameFilters: ["Torch File (*.pt)", "All files (*)"]
        onAccepted: mlBridge.setEstimatePt(selectedFile)
    }

    // ---- The strip -------------------------------------------------------
    // Per-implant .pt pickers (femur/tibia segment + one estimate model —
    // the plan's review fix) with loaded-path labels; Segment/Estimate act
    // on the CURRENT frame only (v1 loop scope); the estimate seeds the
