            horizontalAlignment: Text.AlignHCenter
            color: Theme.fgMuted
            font.pixelSize: Theme.caption
        }
        Label {
            text: qsTr("Y")
            Layout.preferredWidth: 78
            horizontalAlignment: Text.AlignHCenter
            color: Theme.fgMuted
