import QtQuick
import QtQuick.Layouts
import QtQuick.Controls
import QtQuick.Controls.Material  // deliberate: the app pins Material Dark
import QtQuick.Dialogs
import "."  // qmldir: singleton Theme + the U2-extracted components
import jtml.experimental 1.0

// 005 U2/U4/U5 shell + 007 U2 bootstrap — the main screen holds only the
// study lists + viewport + progress; optimizer settings and the pose table
// live in button-opened Dialogs (nothing permanent on the right edge).
// Interaction mode toggle (Camera/Model, #1/#4) sits in the toolbar.
//
// 007 U2: this file is the composition root. Extracted components:
// StudyPanel (frame/model lists), MlStrip (ML controls + its .pt pickers),
// ViewportPanel (renderer + placeholder + readout + scene glue, exposes
// `property alias viewport`), RunBar (run/stop + progress, emits
// runRequested), PosesDialog (pose table + its pose/kinematics pickers),
// PosesTable (the editable table body). Glue split per the wiring
// contract (single owner per bridge signal surface): studyBridge
// dataset/frame sync → StudyPanel; scene relays + selection + the
// viewport-target block → ViewportPanel; this file keeps the studyBridge
// message channel + the optimizer/ml/pose relays (which reach the
// renderer via viewportPanel.viewport).
//
// Surfaces (R17): left column = study lists (frame over model) + ML strip
// (U7); center = the single QmlVtkRenderer viewport; bottom = progress
// (U6); toolbar = load actions + interaction mode + dialog openers.

Window {
    id: root
    visible: true
    width: 1280
    height: 800
    title: qsTr("JTML experimental (QML)")
    color: Theme.bg
    Material.theme: Material.Dark
    Material.accent: Theme.accent

    // ---- Study load + replace confirm + error dialogs (U4) ------------
    FileDialog {
        id: calibrationFileDialog
        title: qsTr("Load Calibration")
        nameFilters: ["Calibration File (*.txt)"]
        onAccepted: studyBridge.loadCalibration(selectedFile)
    }
    // Multi-select via the native Qt file dialog (FileDialogBridge — Qt's
    // in-process dialog, DontUseNativeDialog: immune to the portal backend
    // dispatch that breaks multi-select on this box; see FileDialogBridge.h).
    function pickImages() {
        const files = fileDialogBridge.getOpenFileNames(
                    qsTr("Load Images"),
                    "Image Files (*.tif *.tiff *.png *.TIF *.TIFF *.PNG)",
                    "")
        if (files.length === 0) return
        // A second image set is a new study: confirm, then replace the
        // dataset before loading.
        if (studyBridge.frameCount > 0) {
            replaceDialog.pendingPaths = files
            replaceDialog.open()
        } else {
            studyBridge.loadImages(files)
        }
    }
    function pickModels() {
        const files = fileDialogBridge.getOpenFileNames(
                    qsTr("Load Implant Models"),
                    "CAD File (*.stl *.STL)",
                    "")
        if (files.length === 0) return
        studyBridge.loadModels(files)
    }
    Dialog {
        id: replaceDialog
        property var pendingPaths: []
        title: qsTr("Replace dataset?")
        modal: true
        implicitWidth: 420
        standardButtons: Dialog.Yes | Dialog.No
        contentItem: Label {
            text: qsTr("Loading a new image set replaces the current dataset "
                       + "(frames and models). The calibration stays loaded. "
                       + "Continue?")
            wrapMode: Text.Wrap
        }
        onAccepted: {
            studyBridge.clearDataset()
            studyBridge.loadImages(pendingPaths)
        }
    }
    Dialog {
        id: messageDialog
        property string messageText: ""
        title: ""
        modal: true
        implicitWidth: 420
        standardButtons: Dialog.Ok
        contentItem: Label {
            text: messageDialog.messageText
            wrapMode: Text.Wrap
        }
    }
    function showMessage(title, text) {
        messageDialog.title = title
        messageDialog.messageText = text
        messageDialog.open()
    }

    // ---- Optimizer settings + pose table live in Dialogs (#5) ----------
    Dialog {
        id: settingsDialog
        title: qsTr("Optimizer Settings")
        modal: false
        width: 560
        height: 680
        closePolicy: Popup.CloseOnEscape | Popup.CloseOnPressOutside
        contentItem: SettingsPanel {
            width: settingsDialog.availableWidth
            height: settingsDialog.availableHeight
        }
    }
    PosesDialog {
        id: poseDialog
    }

    // ---- Bridge → view glue -------------------------------------------
    // Study message channel (the dataset/frame-list relay moved to
    // StudyPanel; the scene relays + selection moved to ViewportPanel).
    Connections {
        target: studyBridge
        function onMessageRequested(title, message) {
            showMessage(title, message)
        }
    }

    // ---- Bridge → view glue (U6) ---------------------------------------
    // Optimizer run: the bridge already wrote the scene poses; the glue
    // forwards the pose relays to the renderer's GUI-thread slots, and the
    // error/notice channel reuses the single QML Dialog.
    Connections {
        target: optimizerBridge
        function onPoseUpdated(modelIndex) {
            viewportPanel.viewport.updatePose(modelIndex)
        }
        function onFrameOptimized(frameIndex, modelIndex) {
